SELECT 
    (SELECT AVG(Consumption) FROM yearmonth WHERE Date BETWEEN '201301' AND '201312' AND CustomerID IN (
        SELECT CustomerID FROM transactions_1k WHERE Date BETWEEN '201301' AND '201312' AND Currency = 'CZK' GROUP BY CustomerID ORDER BY SUM(Amount) ASC LIMIT 1
    ) AND Segment = 'SME') -
    (SELECT AVG(Consumption) FROM yearmonth WHERE Date BETWEEN '201301' AND '201312' AND CustomerID IN (
        SELECT CustomerID FROM transactions_1k WHERE Date BETWEEN '201301' AND '201312' AND Currency = 'CZK' GROUP BY CustomerID ORDER BY SUM(Amount) ASC LIMIT 1
    ) AND Segment = 'LAM') AS diff_SME_LAM,

    (SELECT AVG(Consumption) FROM yearmonth WHERE Date BETWEEN '201301' AND '201312' AND CustomerID IN (
        SELECT CustomerID FROM transactions_1k WHERE Date BETWEEN '201301' AND '201312' AND Currency = 'CZK' GROUP BY CustomerID ORDER BY SUM(Amount) ASC LIMIT 1
    ) AND Segment = 'LAM') -
    (SELECT AVG(Consumption) FROM yearmonth WHERE Date BETWEEN '201301' AND '201312' AND CustomerID IN (
        SELECT CustomerID FROM transactions_1k WHERE Date BETWEEN '201301' AND '201312' AND Currency = 'CZK' GROUP BY CustomerID ORDER BY SUM(Amount) ASC LIMIT 1
    ) AND Segment = 'KAM') AS diff_LAM_KAM,

    (SELECT AVG(Consumption) FROM yearmonth WHERE Date BETWEEN '201301' AND '201312' AND CustomerID IN (
        SELECT CustomerID FROM transactions_1k WHERE Date BETWEEN '201301' AND '201312' AND Currency = 'CZK' GROUP BY CustomerID ORDER BY SUM(Amount) ASC LIMIT 1
    ) AND Segment = 'KAM') -
    (SELECT AVG(Consumption) FROM yearmonth WHERE Date BETWEEN '201301' AND '201312' AND CustomerID IN (
        SELECT CustomerID FROM transactions_1k WHERE Date BETWEEN '201301' AND '201312' AND Currency = 'CZK' GROUP BY CustomerID ORDER BY SUM(Amount) ASC LIMIT 1
    ) AND Segment = 'SME') AS diff_KAM_SME;
```

